parameters.query:
WITH context AS (
  SELECT itsm.set_rls_context('{{ String($json.realm).replace(/'/g, "''") }}') AS realm_id
), created AS MATERIALIZED (
  SELECT itsm.core_api_dispatch('{{ String($json.realm).replace(/'/g, "''") }}','create','incident',jsonb_build_object('title','{{ String($json.title).replace(/'/g, "''") }}','priority','p3'),NULL,NULL,50) AS result FROM context
), identified AS (
  SELECT (result->'data'->>'id')::uuid AS id FROM created
), tagged AS MATERIALIZED (
  SELECT itsm.core_api_dispatch('{{ String($json.realm).replace(/'/g, "''") }}','set_tag','incident',jsonb_build_object('key','oq','value','pass'),id,NULL,50) AS result FROM identified
), commented AS MATERIALIZED (
  SELECT itsm.core_api_dispatch('{{ String($json.realm).replace(/'/g, "''") }}','add_comment','incident',jsonb_build_object('body','OQ comment'),id,NULL,50) AS result FROM identified, tagged
), fetched AS MATERIALIZED (
  SELECT itsm.core_api_dispatch('{{ String($json.realm).replace(/'/g, "''") }}','get','incident','{}'::jsonb,id,NULL,50) AS result FROM identified, commented
), removed AS MATERIALIZED (
  SELECT itsm.core_api_dispatch('{{ String($json.realm).replace(/'/g, "''") }}','delete','incident','{}'::jsonb,id,NULL,50) AS result FROM identified, fetched
)
SELECT jsonb_build_object('ok', (SELECT result->>'ok' FROM fetched)='true' AND (SELECT result->>'ok' FROM removed)='true', 'created', (SELECT result FROM created), 'fetched', (SELECT result FROM fetched), 'removed', (SELECT result FROM removed)) AS result;
